"""Lightweight memory value types for the engine runtime.

- :class:`MemoryField` — static declaration of a single typed field, loaded
  from ``memory.yml``.
- :class:`MemoryEntry` — runtime pairing of a :class:`MemoryField` with its
  current value, returned by :class:`~rasa.mantle.memory.manager.MemoryManager`.
- :class:`MemoryItem` — the identity a fully-qualified slot name maps back to
  (owning scope, bare entry name, field declaration), returned by
  :meth:`~rasa.mantle.memory.manager.MemoryManager.reverse_lookup`.
- :class:`PotentialMapping` / :class:`DiscoveredFact` — undeclared,
  user-volunteered facts captured by
  :class:`~rasa.mantle.memory.discovery.extractor.ContextExtractor`
  and stored via
  :meth:`~rasa.mantle.memory.manager.MemoryManager.add_discovered_fact`.
"""

from __future__ import annotations

from typing import Any, Literal, Optional

from pydantic import BaseModel, ConfigDict, Field, model_validator

# Canonical ``MemoryField.type`` strings declared in memory.yml.
MEMORY_FIELD_TYPE_ANY = "any"
MEMORY_FIELD_TYPE_TEXT = "text"
MEMORY_FIELD_TYPE_INT = "int"
MEMORY_FIELD_TYPE_FLOAT = "float"
MEMORY_FIELD_TYPE_BOOL = "bool"
MEMORY_FIELD_TYPE_LIST = "list"
MEMORY_FIELD_TYPE_JSON = "json"
MEMORY_FIELD_TYPE_CATEGORICAL = "categorical"


class MemoryFieldAnonymization(BaseModel):
    """How a ``pii: true`` memory field is anonymized on published events.

    Same keys as a classic privacy-rule ``anonymization`` block. Omitted on a
    PII field means mask the whole value.
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    type: Literal["redact", "mask"]
    redaction_char: str = Field(default="*", min_length=1, max_length=1)
    keep_left: Optional[int] = Field(default=None, gt=0)
    keep_right: Optional[int] = Field(default=None, gt=0)


class MemoryField(BaseModel):
    """Declaration of a single typed memory field, loaded from ``memory.yml``.

    Defines what the field is — its type, description, and privacy.
    Static: shared across all conversations, never changes after model load.
    """

    model_config = ConfigDict(frozen=True)

    type: str = MEMORY_FIELD_TYPE_ANY
    """Value type: text, int, float, bool, list, json, categorical, any."""

    description: str | None = None
    pii: bool = False
    anonymization: MemoryFieldAnonymization | None = None
    """Anonymization method. Valid only when ``pii`` is true."""
    initial_value: Any = None
    privacy_rules: list[str] = Field(default_factory=list)
    enum_values: list[Any] = Field(default_factory=list)

    llm_settable: bool = False
    """Whether the LLM may set this value via ``set_fields``.

    Also gates cross-phase correction discovery (the ``correct`` tool): values a
    ``collect`` step owns are correctable regardless — the engine asked the user
    for them directly — so this flag is only needed for user decisions the LLM
    records in autonomous/instruction steps (e.g. ``replacement_reason``).
    Engine-derived values (eligibility, lock state, computed flags) leave this
    ``False`` so they are never offered for correction or ``set_fields``.
    """

    seed: bool = False
    """Whether session-start metadata may first-write this **project** field.

    Default ``False`` so untrusted channel metadata (including REST) cannot
    lock a privileged flag by name overlap. Set ``True`` only for channel
    facts such as caller phone or language. Train rejects ``seed: true`` on
    skill public and private fields.
    """

    @model_validator(mode="after")
    def anonymization_requires_pii(self) -> "MemoryField":
        """Reject an anonymization method on a field that is not PII."""
        if self.anonymization is not None and not self.pii:
            raise ValueError("anonymization is only valid when pii is true")
        return self


class MemoryEntry(BaseModel):
    """Pairs a memory field's definition with its current runtime value.

    Returned by :meth:`~rasa.mantle.memory.manager.MemoryManager.get`
    and :meth:`~rasa.mantle.memory.manager.MemoryManager.read_all`
    so callers have a single object covering all memory-related operations:

    - Setter tool schema generation:  ``entry.field.type``, ``entry.field.description``
    - Prompt population:              ``entry.field.description``,
      ``entry.field.pii``, ``entry.value``
    - Condition evaluation:           ``entry.value``

    The fully-qualified tracker slot name is not stored here — for
    :meth:`~rasa.mantle.memory.manager.MemoryManager.read_all` callers
    it is the dict key; for
    :meth:`~rasa.mantle.memory.manager.MemoryManager.get` callers the
    slot name is an internal concern of
    :class:`~rasa.mantle.memory.manager.MemoryManager` and can be
    retrieved via
    :meth:`~rasa.mantle.memory.manager.MemoryManager.resolve` if needed.
    """

    model_config = ConfigDict(frozen=True)

    field: MemoryField
    """Static declaration loaded from ``memory.yml``."""

    value: Any = None
    """Current runtime value read from the tracker slot (``None`` if unset)."""


class MemoryItem(BaseModel):
    """Identity a fully-qualified slot name maps back to.

    The inverse of
    :meth:`~rasa.mantle.memory.manager.MemoryManager.resolve`: given a
    tracker slot name (as carried on a memory-write event or in write-provenance),
    :meth:`~rasa.mantle.memory.manager.MemoryManager.reverse_lookup`
    returns this so callers reason in memory items rather than parsing slot
    strings (e.g. cross-phase correction discovery).
    """

    model_config = ConfigDict(frozen=True)

    skill_id: str | None = None
    """Owning skill id for a skill-scoped slot; ``None`` for project-scoped or
    verbatim slots, which carry no single owning skill."""

    entry_name: str
    """Bare memory entry name (e.g. ``shipping_type``), with any namespace
    prefix stripped."""

    field: MemoryField
    """Field declaration resolved from the owning schema, or a bare
    :class:`MemoryField` when the slot is not declared in any schema."""


class PotentialMapping(BaseModel):
    """A declared entry a :class:`DiscoveredFact` could fill.

    Emitted by ``ContextExtractor.discover_facts`` alongside the fact
    itself, so field matching happens in the same extraction call rather
    than a separate background pass.
    """

    model_config = ConfigDict(frozen=True)

    skill_id: str
    """Owning skill of the declared entry this fact could fill."""

    entry: str
    """Bare entry name within that skill (or ``project`` fields)."""

    confidence: float = 1.0
    """0-1 confidence that this fact is a good fill for the entry."""


class DiscoveredFact(BaseModel):
    """A user-volunteered fact not covered by a currently-declared field.

    Stored globally in the engine ``system.__discovered__`` sidecar via
    :meth:`~rasa.mantle.memory.manager.MemoryManager.add_discovered_fact`.
    """

    model_config = ConfigDict(frozen=True)

    key: str
    """Short, model-chosen name for the fact (e.g. ``needs_card_before``)."""

    value: Any
    """The stated value, as free text or a simple scalar."""

    description: str = ""
    """Human-readable summary of what the fact means in conversation context."""

    turn_idx: int
    """Count of user turns elapsed when this fact was captured (freshness)."""

    confidence: float = 1.0
    """0-1 confidence the fact was clearly and unambiguously stated."""

    pii: bool = False
    """Whether the value looks personally identifying (from the LLM's own flag)."""

    captured_by_skill: str | None = None
    """Skill active when the fact was captured, for observability/audit."""

    potential_mappings: list[PotentialMapping] = Field(default_factory=list)
    """Declared entries (any skill) this fact could fill, ranked by confidence."""
